import re, os, sys
HDR = re.compile(r'\(\s*struct\s+(\w+)\s*\*+\s*\)\s*skb->data')
funcs = []
for base in ('net/', 'drivers/net/'):
    for root, dirs, files in os.walk(base):
        dirs[:] = [d for d in dirs if d not in ('selftests',)]
        for f in files:
            if not f.endswith('.c'):
                continue
            p = os.path.join(root, f)
            try:
                src = open(p, encoding='utf-8', errors='replace').read()
            except Exception:
                continue
            lines = src.split('\n')
            # find function bodies: lines starting with '}' at col 0 bound
            fstart = None
            for idx, line in enumerate(lines):
                ls = line.rstrip()
                if ls.endswith('{') and re.match(r'^[A-Za-z_]', line) and not re.match(r'^(if|for|while|switch|else|return|do)\b', line):
                    fstart = idx
                if line.startswith('}') and fstart is not None:
                    body = '\n'.join(lines[fstart:idx+1])
                    nm_m = re.search(r'(\w+)\s*\(', lines[fstart])
                    nm = nm_m.group(1) if nm_m else '?'
                    casts = HDR.findall(body)
                    if casts and re.search(r'(rcv|recv|rx|handler)', nm):
                        has_guard = re.search(r'pskb_may_pull|skb_linearize|skb_header_pointer|skb_headlen|skb_is_nonlinear|skb_pagelen', body)
                        funcs.append((p, fstart+1, nm, casts, bool(has_guard)))
                    fstart = None
print(len(funcs))
for t in funcs[:100]:
    print(f"{t[0]}:{t[1]} {t[2]} casts={t[3]} guarded={t[4]}")
PYEOF
python3 "$T/scan_casts.py"

